import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR, Fondo} from './kit';

const W = 1080;
const H = 1920;

const CANSASTE = en('cansaste');
const ESPERAR = en('esperar');
const RESPUESTA = en('respuesta');
const LLEGA = en('llega');
const ORAR = en('orar');
const SENOR = en('senor');
const PESO = en('peso');
const ESPERA = en('espera');
const CONOCES = en('conoces');
const NOCHES = en('noches');
const SILENCIO = en('silencio');
const DIAS = en('dias');
const FE = en('fe');
const FLACUEAR = en('flaquear');
const GRACIAS = en('gracias');
const NUEVO = en('nuevo');
const AMANECER = en('amanecer');
const MISERICORDIA = en('misericordia');
const AGOTADO = en('agotado');
const PIDO = en('pido');
const RENUEVES = en('renueves');
const FUERZAS = en('fuerzas');
const AGUILA = en('aguila');
const PAZ = en('paz');
const SABER = en('saber');
const VEA = en('vea');
const OBRANDO = en('obrando');
const FAVOR = en('favor');
const CONFIO = en('confio');
const TIEMPOS = en('tiempos');
const MEJORES = en('mejores');
const MIOS = en('mios');
const RECIBO = en('recibo');
const DIA = en('dia');
const ESPERANZA = en('esperanza');
const MANO = en('mano');
const SOSTIENE = en('sostiene');
const MILAGRO = en('milagro');
const CAMINO = en('camino');
const NOMBRE = en('nombre');
const JESUS = en('jesus');
const AMEN = en('amen');

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Cielo: React.FC<{amanecer: number}> = ({amanecer}) => {
  const arriba = mezcla([8, 10, 30], [60, 90, 150], amanecer);
  const medio = mezcla([15, 18, 50], [200, 150, 100], amanecer);
  const abajo = mezcla([25, 28, 60], [255, 220, 160], amanecer);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${arriba} 0%, ${medio} 55%, ${abajo} 100%)`}} />;
};

const Estrellas: React.FC<{s: number; opacidad: number}> = ({s, opacidad}) => (
  <AbsoluteFill style={{opacity: opacidad}}>
    {Array.from({length: 60}).map((_, i) => {
      const x = (i * 173) % W;
      const y = (i * 241) % (H * 0.6);
      const r = 1 + (i % 3);
      const brillo = 0.5 + 0.5 * Math.abs(Math.sin(s * 0.7 + i * 1.3));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r * 2, height: r * 2, borderRadius: r, background: '#fff8e8', opacity: brillo, boxShadow: '0 0 6px #fff0d0'}} />;
    })}
  </AbsoluteFill>
);

const Sol: React.FC<{amanecer: number; s: number}> = ({amanecer, s}) => {
  const y = interpolate(amanecer, [0, 1], [H * 0.9, H * 0.35], clamp);
  const r = 120 + Math.sin(s * 1.1) * 3;
  return (
    <div style={{position: 'absolute', left: W / 2 - r * 2.5, top: y - r * 2.5, width: r * 5, height: r * 5, opacity: amanecer}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,230,170,0.6) 0%, rgba(255,180,100,0.15) 40%, transparent 80%)'}} />
      <div style={{position: 'absolute', left: r * 1.5, top: r * 1.5, width: r * 2, height: r * 2, borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #fffcf0 0%, #ffe8b0 50%, #f5c060 100%)', boxShadow: '0 0 100px 30px rgba(255,215,130,0.5)'}} />
    </div>
  );
};

const Rayos: React.FC<{fuerza: number; s: number}> = ({fuerza, s}) => (
  <AbsoluteFill style={{opacity: fuerza * 0.4, mixBlendMode: 'screen', pointerEvents: 'none'}}>
    {Array.from({length: 7}).map((_, i) => {
      const ang = -30 + i * 10 + Math.sin(s * 0.25 + i) * 1.5;
      return <div key={i} style={{position: 'absolute', left: W / 2 - 30, top: H * 0.35, width: 60, height: H, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,240,200,0.5), transparent 70%)', filter: 'blur(12px)'}} />;
    })}
  </AbsoluteFill>
);

const Colina: React.FC<{y: number; alto: number; colorOscuro: [string, string]; colorClaro: [string, string]; amanecer: number; deriva: number}> = ({
  y, alto, colorOscuro, colorClaro, amanecer, deriva,
}) => {
  const parse = (c: string) => c.match(/\d+/g)!.map(Number);
  const c1 = mezcla(parse(colorOscuro[0]), parse(colorClaro[0]), amanecer);
  const c2 = mezcla(parse(colorOscuro[1]), parse(colorClaro[1]), amanecer);
  const bordeOp = amanecer * 0.9;
  return (
    <svg width={W + 200} height={alto} style={{position: 'absolute', left: -100 + deriva, top: y}} viewBox={`0 0 ${W + 200} ${alto}`}>
      <defs>
        <linearGradient id={`col${y}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={c1} />
          <stop offset="100%" stopColor={c2} />
        </linearGradient>
      </defs>
      <path d={`M0 ${alto * 0.5} C ${W * 0.2} ${alto * 0.15}, ${W * 0.45} ${alto * 0.55}, ${W * 0.65} ${alto * 0.2} S ${W + 100} ${alto * 0.15}, ${W + 200} ${alto * 0.3} L ${W + 200} ${alto} L 0 ${alto} Z`} fill={`url(#col${y})`} />
      <path d={`M0 ${alto * 0.5} C ${W * 0.2} ${alto * 0.15}, ${W * 0.45} ${alto * 0.55}, ${W * 0.65} ${alto * 0.2} S ${W + 100} ${alto * 0.15}, ${W + 200} ${alto * 0.3}`} fill="none" stroke="rgba(255,230,180,0.7)" strokeWidth={3} opacity={bordeOp} />
    </svg>
  );
};

const NubesTormenta: React.FC<{s: number; irse: number}> = ({s, irse}) => (
  <AbsoluteFill style={{opacity: (1 - irse) * 0.8}}>
    {[0, 1, 2].map((i) => (
      <div key={i} style={{position: 'absolute', left: -150 + i * 400 + irse * (i % 2 ? 600 : -600), top: 200 + (i % 2) * 180, width: 500, height: 180, borderRadius: 180, background: 'radial-gradient(ellipse at 50% 40%, #3a3f5a, #1a1d35 70%)', filter: 'blur(8px)'}} />
    ))}
  </AbsoluteFill>
);

const Personaje: React.FC<{s: number; paz: number; levantarse: number; amanecer: number}> = ({s, paz, levantarse, amanecer}) => {
  const respira = Math.sin(s * 1.3) * 2;
  const rodillaY = interpolate(levantarse, [0, 1], [0, -180], clamp);
  const brazosSuben = interpolate(levantarse, [0, 1], [0, 1], clamp);
  const cabezaInclina = interpolate(paz, [0, 1], [0.15, 0], clamp);
  const escala = 1 + paz * 0.05 + amanecer * 0.02;
  const u = 1 * escala;

  return (
    <div style={{position: 'absolute', left: W / 2 - 100 * u, top: H * 0.72 + rodillaY + respira, transform: `scale(${u})`, filter: 'drop-shadow(0 20px 40px rgba(0,0,0,0.4))'}}>
      <div style={{position: 'absolute', left: -80 * u, top: -100 * u, width: 360 * u, height: 360 * u, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,235,180,0.4), transparent 70%)', opacity: paz + amanecer * 0.3}} />
      <svg width={200 * u} height={320 * u} viewBox="0 0 200 320" style={{position: 'absolute', left: 0, top: 0, transformOrigin: '100px 280px', transform: `rotate(${cabezaInclina * -5}deg)`}}>
        <path d="M50 120 Q 30 200 60 280 L 140 280 Q 170 200 150 120 Z" fill="#1a1d3a" />
        <path d="M50 120 Q 30 200 60 280 L 140 280 Q 170 200 150 120 Z" fill="none" stroke="rgba(255,220,160,0.5)" strokeWidth={1} opacity={amanecer} />
        <g transform={`translate(100, 140)`}>
          <line x1={-40 * (1 - brazosSuben)} y1={0} x2={-80 - 40 * brazosSuben} y2={60 + 60 * brazosSuben} stroke="#d4b890" strokeWidth={10} strokeLinecap="round" />
          <line x1={40 * (1 - brazosSuben)} y1={0} x2={80 + 40 * brazosSuben} y2={60 + 60 * brazosSuben} stroke="#d4b890" strokeWidth={10} strokeLinecap="round" />
        </g>
        <circle cx={100} cy={70} r={35} fill="#e8d4b8" />
        <line x1={75} y1={68} x2={90} y2={68} stroke="#2a1a0a" strokeWidth={3} strokeLinecap="round" />
        <line x1={110} y1={68} x2={125} y2={68} stroke="#2a1a0a" strokeWidth={3} strokeLinecap="round" />
      </svg>
    </div>
  );
};

const Aguila: React.FC<{s: number; volar: number}> = ({s, volar}) => {
  const x = interpolate(volar, [0, 1], [W / 2, W / 2 + Math.sin(s * 0.5) * 100], clamp);
  const y = interpolate(volar, [0, 1], [H * 0.6, H * 0.15], {...clamp, easing: Easing.out(Easing.quad)});
  const aleteo = Math.sin(s * 15) * 25 * (1 - volar * 0.3) + volar * 10;
  const opacidad = interpolate(volar, [0, 0.2, 1], [0, 1, 1], clamp);
  return (
    <div style={{position: 'absolute', left: x, top: y, transform: 'translate(-50%, -50%)', opacity: opacidad, pointerEvents: 'none'}}>
      <svg width={180} height={80} viewBox="0 0 180 80">
        <g transform="translate(90, 40)">
          <path d={`M0 0 Q -60 ${-aleteo/2} -90 10 Q -30 0 -60 -10 Q -30 0 0 0`} fill="none" stroke="#fff8e0" strokeWidth={3} opacity={0.9} style={{filter: 'drop-shadow(0 0 8px #ffd98a)'}} />
          <path d={`M0 0 Q 60 ${-aleteo/2} 90 10 Q 30 0 60 -10 Q 30 0 0 0`} fill="none" stroke="#fff8e0" strokeWidth={3} opacity={0.9} style={{filter: 'drop-shadow(0 0 8px #ffd98a)'}} />
        </g>
      </svg>
    </div>
  );
};

const ManoLuz: React.FC<{s: number; aparece: number}> = ({s, aparece}) => (
  <div style={{position: 'absolute', left: W / 2, top: H * 0.25, width: 240, height: 300, transform: 'translate(-50%, -50%)', opacity: aparece, pointerEvents: 'none'}}>
    <svg width={240} height={300} viewBox="0 0 240 300" style={{filter: 'drop-shadow(0 0 30px #ffe8b0)'}}>
      <defs>
        <radialGradient id="manoGrad" cx="50%" cy="30%" r="60%">
          <stop offset="0%" stopColor="#fffdf0" stopOpacity={0.9} />
          <stop offset="100%" stopColor="#ffd98a" stopOpacity={0.3} />
        </radialGradient>
      </defs>
      <path d="M120 50 C 80 50, 40 100, 40 150 C 40 200, 80 250, 120 280 C 160 250, 200 200, 200 150 C 200 100, 160 50, 120 50 Z" fill="url(#manoGrad)" />
      <path d="M80 150 Q 90 180 100 200 Q 110 220 120 230 Q 130 220 140 200 Q 150 180 160 150" fill="none" stroke="#ffe8b0" strokeWidth={2} opacity={0.6} />
    </svg>
  </div>
);

const ParticulasLuz: React.FC<{s: number; intensidad: number}> = ({s, intensidad}) => (
  <AbsoluteFill style={{pointerEvents: 'none'}}>
    {Array.from({length: 50}).map((_, i) => {
      const x = (i * 149) % W + Math.sin(s * 0.4 + i) * 40;
      const y = H - ((i * 197 + s * (15 + intensidad * 30 + (i % 5) * 10)) % (H + 200));
      const r = 2 + (i % 4);
      const color = intensidad > 0.5 ? '#fff3c0' : '#a8c0ff';
      const op = 0.2 + 0.4 * intensidad * (0.5 + 0.5 * Math.sin(s + i));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: color, opacity: op, filter: 'blur(0.5px)'}} />;
    })}
  </AbsoluteFill>
);

const CaminoLuz: React.FC<{s: number; abre: number}> = ({s, abre}) => {
  const k = interpolate(abre, [0, 1], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  return (
    <svg width={W} height={H * 0.5} style={{position: 'absolute', left: 0, top: H * 0.5}} viewBox={`0 0 ${W} ${H * 0.5}`}>
      <defs>
        <linearGradient id="caminoGrad" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="rgba(255,230,160,0)" />
          <stop offset="50%" stopColor="rgba(255,240,200,0.6)" />
          <stop offset="100%" stopColor="rgba(255,250,220,0)" />
        </linearGradient>
      </defs>
      <path d={`M${W * 0.5} ${H * 0.5} Q ${W * 0.45} ${H * 0.3} ${W * 0.48} ${H * 0.1} L ${W * 0.52} ${H * 0.1} Q ${W * 0.55} ${H * 0.3} ${W * 0.5} ${H * 0.5} Z`} fill="url(#caminoGrad)" opacity={k} style={{filter: 'blur(4px)'}} />
      <ellipse cx={W/2} cy={H*0.05} rx={200 * k} ry={40 * k} fill="rgba(255,245,200,0.4)" style={{filter: 'blur(20px)'}} />
    </svg>
  );
};

export const Escena: React.FC = () => {
  const {s} = useS();

  const amanecer = interpolate(s, [PAZ - 0.5, PAZ + 4], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const nubesIrse = interpolate(s, [GRACIAS, GRACIAS + 3], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const pazInterna = interpolate(s, [PAZ, PAZ + 3], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const levantarse = interpolate(s, [CONFIO, CONFIO + 2], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const aguilaVolar = interpolate(s, [FUERZAS, FUERZAS + 4], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const manoAparece = interpolate(s, [MANO, MANO + 1.5], [0, 1], clamp);
  const caminoAbre = interpolate(s, [CAMINO, CAMINO + 2], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const particulasInt = interpolate(s, [AMANECER, AMANECER + 5], [0.2, 1], clamp);
  const deriva = Math.sin(s * 0.1) * 15;
  const zoom = 1.05 - 0.03 * (s / Math.max(DUR, 1));
  const finalGlow = interpolate(s, [AMEN, AMEN + 1.5], [0, 1], clamp);

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0a0f24'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 60%'}}>
        <Fondo colores={['#1a0a3a', '#0d0620', '#050210']} manchas={['rgba(120,80,180,0.15)', 'rgba(255,150,100,0.1)']} particulas="#ffd98a" cantidad={20} />
        <Cielo amanecer={amanecer} />
        <Estrellas s={s} opacidad={1 - amanecer} />
        <Sol amanecer={amanecer} s={s} />
        <Rayos fuerza={amanecer + finalGlow * 0.3} s={s} />
        <NubesTormenta s={s} irse={nubesIrse} />
        <Colina y={1000} alto={520} colorOscuro={['#2a2f55', '#171a36']} colorClaro={['#7a6a8e', '#4a3e62']} amanecer={amanecer} deriva={deriva * 0.3} />
        <Colina y={1160} alto={760} colorOscuro={['#1d2244', '#0e1028']} colorClaro={['#5e5a7a', '#2c2840']} amanecer={amanecer} deriva={deriva * 0.6} />
        <CaminoLuz s={s} abre={caminoAbre} />
        <Personaje s={s} paz={pazInterna} levantarse={levantarse} amanecer={amanecer} />
        <Aguila s={s} volar={aguilaVolar} />
        <ManoLuz s={s} aparece={manoAparece} />
        <ParticulasLuz s={s} intensidad={particulasInt} />
      </AbsoluteFill>
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 55%, transparent 55%, rgba(5,6,20,0.55) 100%)'}} />
    </AbsoluteFill>
  );
};
